<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Enable;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetEnableUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateAssetVisibilityService $visibility,
        private readonly TemplateAssetWriteGateway $writer,
    ) {
    }

    public function allowEnable(?TemplateAssetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of Enable usecase for Template asset");
        $span = $this->startSpan("Check allow of Enable usecase for Template asset");
        try {
            $result = $this->dispatcher->dispatch(new TemplateAssetEnableAllowDecision(Allow::allowed('enable', 'Allowed to Template asset by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function enable(string $uid): TemplateAssetEnableResult
    {
        $this->logDebug("Run Enable usecase for Template asset");
        $span = $this->startSpan("Run Enable usecase for Template asset");
        try {
            $ref = new TemplateAssetRef($uid);
            $allow = $this->allowEnable($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to Enable Template asset');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new TemplateAssetEnableCheck($original));
            $modified = $original->enable();
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateAssetEnableResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
